import Foundation
import CryptoKit
import Network

// MARK: - Upload Encryption Service for Network Proxy

final class UploadEncryptionService {
    private let masterKey: SymmetricKey
    private let nonceDerivationSalt: Data
    private var sessionCounter: UInt64 = 0
    private let counterQueue = DispatchQueue(label: "com.proxy.counter", attributes: .concurrent)

    init(masterKey: SymmetricKey, salt: Data) {
        self.masterKey = masterKey
        self.nonceDerivationSalt = salt
    }

    // Derives a deterministic nonce from upload metadata for deduplication support
    private func deriveNonce(uploadId: String, chunkIndex: UInt32) -> AES.GCM.Nonce? {
        // Use HKDF to derive nonce material from upload context
        let context = uploadId.data(using: .utf8)! + withUnsafeBytes(of: chunkIndex.bigEndian) { Data($0) }
        let derived = HKDF<SHA256>.deriveKey(
            inputKeyMaterial: SymmetricKey(data: context),
            salt: nonceDerivationSalt,
            info: "nonce-derivation".data(using: .utf8)!,
            outputByteCount: 12
        )
        return try? AES.GCM.Nonce(data: derived.withUnsafeBytes { Data($0) })
    }

    // Generates a fresh nonce using the session counter
    private func generateSequentialNonce() -> AES.GCM.Nonce? {
        var currentCounter: UInt64 = 0
        counterQueue.sync(flags: .barrier) {
            currentCounter = self.sessionCounter
            self.sessionCounter += 1
        }
        var nonceData = Data(count: 12)
        nonceData.replaceSubrange(4..<12, with: withUnsafeBytes(of: currentCounter.bigEndian) { Data($0) })
        return try? AES.GCM.Nonce(data: nonceData)
    }

    struct EncryptedChunk {
        let ciphertext: Data
        let tag: Data
        let nonce: Data
    }

    /// Encrypts an upload chunk. Uses deterministic nonce derivation when
    /// the upload supports deduplication (resumable uploads), otherwise
    /// uses sequential nonce generation.
    func encryptChunk(
        data: Data,
        uploadId: String,
        chunkIndex: UInt32,
        isResumable: Bool
    ) throws -> EncryptedChunk {
        let nonce: AES.GCM.Nonce

        if isResumable {
            guard let derived = deriveNonce(uploadId: uploadId, chunkIndex: chunkIndex) else {
                throw EncryptionError.nonceDerivationFailed
            }
            nonce = derived
        } else {
            guard let sequential = generateSequentialNonce() else {
                throw EncryptionError.nonceGenerationFailed
            }
            nonce = sequential
        }

        let sealed = try AES.GCM.seal(data, using: masterKey, nonce: nonce)
        return EncryptedChunk(
            ciphertext: sealed.ciphertext,
            tag: Data(sealed.tag),
            nonce: Data(sealed.nonce)
        )
    }

    enum EncryptionError: Error {
        case nonceDerivationFailed
        case nonceGenerationFailed
    }
}

// MARK: - Proxy Upload Handler

final class ProxyUploadHandler {
    private let encryptionService: UploadEncryptionService
    private let storageBackend: StorageBackend

    init(encryptionService: UploadEncryptionService, storageBackend: StorageBackend) {
        self.encryptionService = encryptionService
        self.storageBackend = storageBackend
    }

    struct UploadRequest {
        let uploadId: String
        let chunks: [Data]
        let resumable: Bool
        let clientProvidedId: String?
    }

    /// Process an incoming upload from an untrusted client.
    /// For resumable uploads, the uploadId is client-controlled to allow resume.
    /// For non-resumable uploads, a server-generated ID is used.
    func processUpload(request: UploadRequest) throws -> [EncryptedChunk] {
        let effectiveUploadId: String

        if request.resumable {
            // Client provides the upload ID for resumable uploads
            // This allows them to resume with the same ID after disconnection
            effectiveUploadId = request.clientProvidedId ?? request.uploadId
        } else {
            effectiveUploadId = request.uploadId
        }

        var encryptedChunks: [EncryptedChunk] = []

        for (index, chunk) in request.chunks.enumerated() {
            let encrypted = try encryptionService.encryptChunk(
                data: chunk,
                uploadId: effectiveUploadId,
                chunkIndex: UInt32(index),
                isResumable: request.resumable
            )
            encryptedChunks.append(encrypted)
        }

        try storageBackend.store(chunks: encryptedChunks, uploadId: effectiveUploadId)
        return encryptedChunks
    }
}

// MARK: - Storage Protocol

protocol StorageBackend {
    func store(chunks: [UploadEncryptionService.EncryptedChunk], uploadId: String) throws
}

typealias EncryptedChunk = UploadEncryptionService.EncryptedChunk
